// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: from address, callee address (we will deploy a helper and pass its address),
    // array of tos length (we model by passing bytes for dynamic arrays not allowed in fuzz signature),
    // value and decimals. Foundry can fuzz address, uint256, and bytes; but simplest is to fuzz uint256s and an address.
    // We take: address fromAddr, uint256 v, uint256 decimals, uint256 tosCount
    function testFuzz_property(address fromAddr, uint256 v, uint256 decimals, uint256 tosCount) public {
        // keep decimals reasonable to avoid overflow in v * 10 ** decimals
        vm.assume(decimals <= 18);
        // tosCount should be at least 1 as require(_tos.length > 0)
        uint256 n = bound(tosCount, 1, 5);

        // deploy a benign callee that always returns true from transferFrom simulation
        CalleeAlwaysSucceeds callee = new CalleeAlwaysSucceeds();

        // build dynamic address[] memory _tos with n entries pointing to arbitrary addresses
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // use distinct addresses derived from i and fromAddr to keep variety
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(fromAddr, i)))));
        }

        // Call transfer and capture whether it returned (completed) and the bool result using try/catch on low-level call to get return data
        // Since C.transfer is public and returns (bool), we can call it and get the returned value directly.
        bool ok;
        bool ret;
        try c.transfer(fromAddr, address(callee), tos, v, decimals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General rule: If the call completed (ok == true) then the reference implementation returns true.
        // We assert that whenever transfer completes, it returned true. This holds for the reference and the mutant breaks it
        // because the mutant returns false on completion.
        assertTrue(!ok || ret);
    }
}

// A minimal helper callee that simulates an external contract with a transferFrom selector
contract CalleeAlwaysSucceeds {
    // simulate function: transferFrom(address from, address to, uint256 amount) external returns (bool)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // also accept fallback to handle low-level calls
    fallback() external payable {
    }
}
